  const d=state.decks[0],track=d.track,sr=44100,duration=8,b=engine.ctx.createBuffer(2,sr*duration,sr);for(let c=0;c<2;c++){const a=b.getChannelData(c),hz=c?550:330;for(let n=0;n<a.length;n++)a[n]=.12*Math.sin(2*Math.PI*hz*n/sr);}
  Object.assign(track,{duration,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true});delete track.stemJob;Object.assign(d,{position:1,rate:1,keylock:false,keyShift:0,reverse:false,loop:true,loopIn:0,loopOut:4,slip:false,stemSlip:'off',sync:false,mode:'INT',level:.8,stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(0);engine.stemBuffers.delete(track.id);engine.buffers.set(track.id,b);engine.mix(0,'level',.8);state.selected=track.id;
  report.originalPCMHash=await hash(b.getChannelData(0).buffer);click(button(0,'tab')+'[data-tab="Stems"]');click(button(0,'stemPrepare'));assert($('#stems-clear').disabled,'No previous job should be clearable');click('#stems-queue');await until(()=>engine.stemBuffers.has(track.id)&&track.stemJob&&!$('#stems-queue').disabled,'First real SCNet preparation');report.firstJob=track.stemJob;report.firstAPI=await(await fetch('/api/stems/'+report.firstJob)).json();assert(report.firstAPI.model==='SCNet-large official'&&report.firstAPI.state==='complete','Actual SCNet required');assert(JSON.parse(localStorage.getItem('openplay-review-v1')).tags[track.id].stemJob===report.firstJob,'Prepared association not persisted');click('#modal-close');
